import pytest

from bedrock_protocol import v1001, v2168

# generated by gophertunnel 0a2ecd5:
# packet.ItemStackResponse{Responses: []protocol.ItemStackResponse{{Status: 0, RequestID: -1,
# ContainerInfo: []protocol.StackResponseContainerInfo{{Container: {ContainerID: 12},
# SlotInfo: []protocol.StackResponseSlotInfo{{Slot: 3, HotbarSlot: 3, Count: 64,
# StackNetworkID: 9, CustomName: "", FilteredCustomName: "", DurabilityCorrection: 0}}}}}}}
OK_V1001 = bytes.fromhex("010001010c000103034012000000")

# generated by gophertunnel 0a2ecd5:
# packet.ItemStackResponse{Responses: []protocol.ItemStackResponse{{Status: 1, RequestID: -1}}}
ERROR_V1001 = bytes.fromhex("010101")

# generated by gophertunnel b8bd735:
# packet.ItemStackResponse{Responses: []protocol.ItemStackResponse{{Status: 0, RequestID: -1,
# ContainerInfo: []protocol.StackResponseContainerInfo{{Container: {ContainerID: 7},
# SlotInfo: []protocol.StackResponseSlotInfo{{Slot: 3, HotbarSlot: 3, Count: 64, StackNetworkID: 9}}}}}}}
OK_V2168 = bytes.fromhex("010001010101070001030340010112000000")

# generated by gophertunnel b8bd735:
# packet.ItemStackResponse{Responses: []protocol.ItemStackResponse{{Status: 1, RequestID: -1}}}
ERROR_V2168 = bytes.fromhex("0101010100")

GOLDENS = [
    pytest.param(
        v1001.ItemStackResponsePacket(
            responses=[
                v1001.ItemStackResponseInfo(
                    result=v1001.ItemStackNetResult.SUCCESS,
                    client_request_id=v1001.ItemStackRequestId(raw_id=-1),
                    containers=[
                        v1001.ItemStackResponseContainerInfo(
                            full_container_name=v1001.FullContainerName(
                                name=v1001.ContainerEnumName.COMBINED_HOTBAR_AND_INVENTORY_CONTAINER
                            ),
                            slots=[
                                v1001.ItemStackResponseSlotInfo(
                                    requested_slot=3,
                                    slot=3,
                                    amount=64,
                                    item_stack_net_id=v1001.ItemStackNetId(raw_id=9),
                                )
                            ],
                        )
                    ],
                )
            ]
        ),
        OK_V1001,
        id="v1001-success",
    ),
    pytest.param(
        v1001.ItemStackResponsePacket(
            responses=[
                v1001.ItemStackResponseInfo(
                    result=v1001.ItemStackNetResult.ERROR,
                    client_request_id=v1001.ItemStackRequestId(raw_id=-1),
                )
            ]
        ),
        ERROR_V1001,
        id="v1001-error",
    ),
    pytest.param(
        v2168.ItemStackResponsePacket(
            responses=[
                v2168.ItemStackResponseInfo(
                    result=v2168.ItemStackNetResult.SUCCESS,
                    client_request_id=v2168.ItemStackRequestId(raw_id=-1),
                    containers=[
                        v2168.ItemStackResponseContainerInfo(
                            full_container_name=v2168.FullContainerName(
                                name=v2168.ContainerEnumName.LEVEL_ENTITY_CONTAINER
                            ),
                            slots=[
                                v2168.ItemStackResponseSlotInfo(
                                    requested_slot=3,
                                    slot=3,
                                    amount=64,
                                    item_stack_net_id=v2168.ItemStackNetId(raw_id=9),
                                )
                            ],
                        )
                    ],
                )
            ]
        ),
        OK_V2168,
        id="v2168-success",
    ),
    pytest.param(
        v2168.ItemStackResponsePacket(
            responses=[
                v2168.ItemStackResponseInfo(
                    result=v2168.ItemStackNetResult.ERROR,
                    client_request_id=v2168.ItemStackRequestId(raw_id=-1),
                    containers=None,
                )
            ]
        ),
        ERROR_V2168,
        id="v2168-error",
    ),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_item_stack_response_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_item_stack_response_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize(
    "body",
    [
        pytest.param(bytes.fromhex("010001000101070001030340010112000000"), id="container-list-marker"),
        pytest.param(bytes.fromhex("010001010101070001030340000112000000"), id="slot-net-id-marker"),
    ],
)
def test_item_stack_response_2168_rejects_a_marker_that_reads_false(body):
    with pytest.raises(ValueError, match="at byte"):
        v2168.ItemStackResponsePacket.from_bytes(body)


def test_item_stack_response_2168_rejects_a_1001_body():
    with pytest.raises(ValueError, match="at byte"):
        v2168.ItemStackResponsePacket.from_bytes(ERROR_V1001)


def test_item_stack_response_1001_rejects_a_2168_body():
    with pytest.raises(ValueError, match="at byte"):
        v1001.ItemStackResponsePacket.from_bytes(OK_V2168)
